import{_ as t,c as a,o as i,a3 as s}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Products and pricing","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/products-pricing/index.md","filePath":"master/sales/point-of-sale/products-pricing/index.md","lastUpdated":1793074831000}'),r={name:"master/sales/point-of-sale/products-pricing/index.md"};function o(l,e,n,c,d,h){return i(),a("div",null,e[0]||(e[0]=[s('<h1 id="products-and-pricing" tabindex="-1">Products and pricing <a class="header-anchor" href="#products-and-pricing" aria-label="Permalink to &quot;Products and pricing&quot;">​</a></h1><p>Before you can sell at the till, you need products to sell and prices to charge. This group shows how products reach the terminal, how categories organise the product grid, and how taxes and discounts change the final price.</p><blockquote><p><strong>In simple words:</strong> Choose what to sell, group it in tiles, set the price and tax, then it shows at the till.</p></blockquote><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><ol><li>Create or open a product. Switch on <strong>Available in POS</strong> and pick its <strong>PoS Product Categories</strong>. See <a href="./products.html">Products</a>.</li><li>Create the categories that become the tiles on the terminal. See <a href="./categories-and-attributes.html">Categories and attributes</a>.</li><li>Decide if prices include tax, which taxes apply, and whether cashiers can give discounts. See <a href="./pricing-and-taxes.html">Pricing and taxes</a>.</li><li>Open the register. The product grid shows your products with their price.</li></ol><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><ul><li><a href="./products.html">Products</a>: the product list, its tabs and the POS fields.</li><li><a href="./categories-and-attributes.html">Categories and attributes</a>: PoS product categories and attributes.</li><li><a href="./pricing-and-taxes.html">Pricing and taxes</a>: tax display, price lists and discounts.</li></ul><h2 id="where-each-item-lives" tabindex="-1">Where each item lives <a class="header-anchor" href="#where-each-item-lives" aria-label="Permalink to &quot;Where each item lives&quot;">​</a></h2><ul><li>Products: <code>Point of Sale → Products</code>.</li><li>Categories, Attributes and Taxes: <code>Point of Sale → Configurations</code>.</li><li>Price lists: <code>Point of Sale → Products → Price Lists</code>, once price lists are switched on.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Products are shared with Sales and Inventory. A product you change here changes there too.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../sales/products-prices/manage-products.html">Manage products in Sales</a></li><li><a href="./../get-started/set-up-a-register.html">Set up a register</a></li></ul>',12)]))}const g=t(r,[["render",o]]);export{u as __pageData,g as default};
